sys_script.script:
(function executeRule(current, previous) {

    // Confirm that the Requested Item moved to Pending.
    if (current.state != '-5') {
        return;
    }

    var ritmNumber = current.getValue('number');
    var shortDescription = 'License issue for ' + ritmNumber;

    // Prevent duplicate incidents for this Requested Item.
    var existing = new GlideRecord('incident');
    existing.addQuery('short_description', shortDescription);
    existing.addQuery(
        'description',
        'CONTAINS',
        'Requested Item: ' + ritmNumber
    );
    existing.setLimit(1);
    existing.query();

    if (existing.next()) {
        return;
    }

    // Initialize a new Incident.
    var inc = new GlideRecord('incident');
    inc.initialize();

    inc.setValue('short_description', shortDescription);

    inc.setValue(
        'description',
        'The software request requires investigation due to a license issue.\n' +
        'Requested Item: ' + ritmNumber + '\n' +
        'Please verify license availability and determine the next action.'
    );

    // Set the caller from the Requested Item.
    var requestedFor = current.getValue('requested_for');

    if (requestedFor) {
        inc.setValue('caller_id', requestedFor);
    }

    // Set impact and urgency to low.
    inc.setValue('impact', '3');
    inc.setValue('urgency', '3');

    // Assign to Software Support if the group exists.
    var group = new GlideRecord('sys_user_group');
    group.addQuery('name', 'Software Support');
    group.setLimit(1);
    group.query();

    if (group.next()) {
        inc.setValue('assignment_group', group.getUniqueValue());
    }

    // Insert the Incident.
    var incidentId = inc.insert();

    if (!incidentId) {
        gs.error(
            'Failed to create Incident for Requested Item ' + ritmNumber
        );
    }

})(current, previous);
